// CA1707: Test method names use underscores intentionally.
#pragma warning disable CA1707
// MA0004: ConfigureAwait not needed in test bodies.
#pragma warning disable MA0004
// MLFH001: Compat48Quoted and Compat48Fixed have no record attributes on purpose (see Generated48).
#pragma warning disable MLFH001

using TUnit.Core;

namespace ModernLibs.FileHelpers.Tests.Compat;

/// <summary>
/// A library compiled against 4.8.0 carries descriptors generated by the 4.8.0 generator. On the current runtime
/// they must read and write exactly as the descriptors the current generator makes for the same record.
/// </summary>
[Category("Compat")]
public sealed class Compat48Tests
{
    private const string QuotedInput =
        "id,name,amount,day,code,count,note\r\n" +
        "1,\"Smith, John\",12.50,2026-11-08,  A1  ,3,\"first\"\r\n" +
        "2,plain,0.1,2024-02-29,B2,,\r\n" +
        "3,\"multi\r\nline \"\"quoted\"\"\",-7,1999-12-31,C3,10\r\n" +
        "4,bad,x.5,2026-01-01,D4,1,\r\n" +
        "5,\"unclosed,1,2026-01-01,E5,1,\r\n";

    private const string FixedInput =
        "000001Alice     08112026000012.50\r\n" +
        "000002Bob       29022024000000.10\r\n" +
        "00000xBad       01012026000001.00\r\n" +
        "000004Carol     31121999000007.00\r\n";

    private static string Errors(ErrorManager manager) =>
        string.Join("|", manager.Errors.Select(e => $"{e.LineNumber}:{e.RecordString}:{e.ExceptionInfo?.GetType().Name}:{e.ExceptionInfo?.Message}"));

    [Test]
    [DisplayName("A 4.8.0 delimited descriptor reads, reports errors and writes as the current one")]
    public async Task Delimited_MatchesCurrentDescriptor()
    {
        // Arrange
        var old = new FileHelperEngine<Compat48Quoted> { ErrorMode = ErrorMode.SaveAndContinue };
        var current = new FileHelperEngine<Compat48QuotedTwin> { ErrorMode = ErrorMode.SaveAndContinue };

        // Act
        var oldRecords = old.ReadString(QuotedInput);
        var currentRecords = current.ReadString(QuotedInput);
        string oldText = old.WriteString(oldRecords);
        string currentText = current.WriteString(currentRecords);

        // Assert: the same values, errors (the class name aside), header and written text
        string Show(int id, string name, decimal amount, DateTime day, string code, int? count, string? note) =>
            $"{id}|{name}|{amount}|{day:o}|{code}|{count}|{note}";
        await Assert.That(string.Join("\n", oldRecords.Select(r => Show(r.Id, r.Name, r.Amount, r.Day, r.Code, r.Count, r.Note))))
            .IsEqualTo(string.Join("\n", currentRecords.Select(r => Show(r.Id, r.Name, r.Amount, r.Day, r.Code, r.Count, r.Note))));
        await Assert.That(oldRecords.Length).IsEqualTo(3);
        await Assert.That(Errors(old.ErrorManager)).IsEqualTo(Errors(current.ErrorManager).Replace("Compat48QuotedTwin", "Compat48Quoted", StringComparison.Ordinal));
        await Assert.That(old.ErrorManager.ErrorCount).IsEqualTo(2);
        await Assert.That(old.HeaderText).IsEqualTo(current.HeaderText);
        await Assert.That(oldText).IsEqualTo(currentText);
    }

    [Test]
    [DisplayName("A 4.8.0 fixed-length struct descriptor reads, reports errors and writes as the current one")]
    public async Task FixedLength_MatchesCurrentDescriptor()
    {
        // Arrange
        var old = new FileHelperEngine<Compat48Fixed> { ErrorMode = ErrorMode.SaveAndContinue };
        var current = new FileHelperEngine<Compat48FixedTwin> { ErrorMode = ErrorMode.SaveAndContinue };

        // Act
        var oldRecords = old.ReadString(FixedInput);
        var currentRecords = current.ReadString(FixedInput);
        string oldText = old.WriteString(oldRecords);
        string currentText = current.WriteString(currentRecords);

        // Assert
        await Assert.That(string.Join("\n", oldRecords.Select(r => $"{r.Id}|{r.Name}|{r.Day:o}|{r.Amount}")))
            .IsEqualTo(string.Join("\n", currentRecords.Select(r => $"{r.Id}|{r.Name}|{r.Day:o}|{r.Amount}")));
        await Assert.That(oldRecords.Length).IsEqualTo(3);
        await Assert.That(Errors(old.ErrorManager)).IsEqualTo(Errors(current.ErrorManager).Replace("Compat48FixedTwin", "Compat48Fixed", StringComparison.Ordinal));
        await Assert.That(oldText).IsEqualTo(currentText);
    }

    [Test]
    [DisplayName("The 4.8.0 descriptors also work through the file, stream and callback reads")]
    public async Task OtherReadPaths_MatchReadString()
    {
        // Arrange
        var engine = new FileHelperEngine<Compat48Quoted> { ErrorMode = ErrorMode.SaveAndContinue };
        string expected = string.Join("\n", engine.ReadString(QuotedInput).Select(r => $"{r.Id}|{r.Name}|{r.Amount}"));
        var path = Path.GetTempFileName();
        try
        {
            await File.WriteAllTextAsync(path, QuotedInput);

            // Act
            string file = string.Join("\n", engine.ReadFile(path).Select(r => $"{r.Id}|{r.Name}|{r.Amount}"));
            string stream = string.Join("\n", engine.ReadStream(new StringReader(QuotedInput)).Select(r => $"{r.Id}|{r.Name}|{r.Amount}"));
            var callback = new List<string>();
            engine.ReadFile(path, r => callback.Add($"{r.Id}|{r.Name}|{r.Amount}"));
            var asyncRead = new List<string>();
            await foreach (var r in engine.ReadAsync(path))
                asyncRead.Add($"{r.Id}|{r.Name}|{r.Amount}");

            // Assert
            await Assert.That(file).IsEqualTo(expected);
            await Assert.That(stream).IsEqualTo(expected);
            await Assert.That(string.Join("\n", callback)).IsEqualTo(expected);
            await Assert.That(string.Join("\n", asyncRead)).IsEqualTo(expected);
        }
        finally
        {
            File.Delete(path);
        }
    }
}
